      "issues": [
        {
          "dimension": "theme_direction",
          "detail": "theme_map.self 为 0.2；每日运势条目按项目约定须全部为 0，应将该值改为 0。"
        }
      ],
      "reason": "释义及配色符合约定，但每日运势条目不应设置非零方向。"
    },
    {
      "item": "i02",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "certainty",
          "detail": "text 中“可以为当天带来好运”暗示配色能带来实际运气，违反每日运势配色仅为约定的要求，应删除或改为不带来实际运气的说明。"
        }
      ],
      "reason": "木的配色正确且方向中性，但对幸运色实际作用的表述不符合项目约定。"
    },
    {
      "item": "i03",
      "verdict": "revise",
      "issues": [
        {
          "dimension": "tradition",
          "detail": "text 中“传统配色为黑、蓝”与金的参考配色不符；黑、蓝对应水，金应为白、金。"
        }
      ],
      "reason": "条目对象仍为金，但其传统配色写错，需要修正。"
    }
  ]
}
